async function api(path:string,body?:any){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Mo-Hoc':'1'},body:body===undefined?undefined:JSON.stringify(body)});const j:any=await r.json();if(!r.ok){const e:any=new Error(j.error||'Không thể kết nối.');e.status=r.status;throw e;}return j;}
function Icon({color,size=22}:{color:string;size?:number}){const C=color==='mint'?Code2:color==='peach'?Palette:color==='lavender'?ChartNoAxesCombined:color==='blue'?Cloud:color==='yellow'?Lightbulb:Presentation;return <C size={size}/>;}
function Art({color='mint',large=false}:{color?:string;large?:boolean}){return <div className={`course-art ${color} ${large?'large':''}`} aria-hidden="true"><span className="art-grid"/>{color==='mint'?<div className="code-art"><div className="code-dots"><i/><i/><i/></div><div className="code-body"><span>&lt;hello world&gt;</span><b/><em/><b/><span>&lt;/your future&gt;</span></div><div className="code-cursor"><Code2 size={31}/></div></div>:color==='peach'?<div className="design-art"><div className="design-circle"/><div className="design-square"/><div className="design-star">✳</div><i/><b/></div>:color==='lavender'?<div className="chart-art"><div className="chart-head"><span/><i/></div><div className="chart-bars"><b/><b/><b/><b/><b/></div><div className="chart-bubble"><ArrowUpRight size={25}/></div></div>:color==='blue'?<div className="cloud-art"><Cloud size={100} strokeWidth={1.5}/><span/><i/><b/></div>:color==='yellow'?<div className="idea-art"><Lightbulb size={100} strokeWidth={1.4}/><span>+1</span></div>:<div className="slide-art"><Presentation size={98} strokeWidth={1.3}/><span>“</span></div>}<span className="art-label">{color==='mint'?'CREATE.':color==='peach'?'IMAGINE.':color==='lavender'?'DISCOVER.':color==='blue'?'CONNECT.':color==='yellow'?'GROW.':'SHARE.'}</span></div>}
function Progress({value}:{value:number}){return <div className="progress" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={value}><i style={{width:value+'%'}}/></div>}
function CourseCard({c,mine=false}:{c:any;mine?:boolean}){return <button className="course-card" onClick={()=>nav(`course/${c.id}`)}><Art color={c.color}/><div className="course-info"><div className="card-meta"><span className={`tag ${c.color}`}>{c.category}</span><span>{c.level}</span></div><h3>{c.title}</h3><p>{c.description}</p>{mine?<div className="card-bottom progress-bottom"><span>{c.completed}/{c.required_count??c.lesson_count} bài bắt buộc</span><strong>{pct(c)}%</strong><Progress value={pct(c)}/></div>:<div className="card-bottom"><span><BookOpen size={14}/>{c.lesson_count} bài học</span><span><Clock size={14}/>{c.minutes} phút</span><span className="course-price-label">{c.price_vnd>0?formatVnd(c.price_vnd):'Miễn phí'}</span><ArrowUpRight size={17}/></div>}</div></button>}
function Modal({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const prior=document.activeElement as HTMLElement;ref.current?.querySelector<HTMLElement>('button,input,textarea,select')?.focus();const listener=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const items=ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input,textarea,select,a[href]');if(!items?.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',listener);return()=>{document.removeEventListener('keydown',listener);prior?.focus();};},[]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal" ref={ref} role="dialog" aria-modal="true" aria-label={title}><div className="modal-title"><h2>{title}</h2><button className="icon-btn" onClick={onClose} aria-label="Đóng"><X size={20}/></button></div>{children}</div></div>}
function Blank({icon=<BookOpen/>,title,body,action}:{icon?:ReactNode;title:string;body:string;action?:ReactNode}){return <div className="blank"><div>{icon}</div><h3>{title}</h3><p>{body}</p>{action}</div>}
