 {page==='explore'&&<><div className="page-title-row"><div><div className="eyebrow">TÒ MÒ LÀ ĐIỂM KHỞI ĐẦU</div><h1>Bạn muốn khám phá điều gì?</h1><p>Những khóa học ngắn, thiết thực. Bắt đầu theo nhịp của bạn.</p></div><span className="pill neutral">{catalog?.total??state.courses.filter(c=>c.status==='PUBLISHED'&&!c.hidden&&!c.sale_pending_review).length} khóa học</span></div><div className="catalog-tools"><div className="filter-tabs">{['Tất cả',...categoryNames].map(c=><button key={c} className={filter===c?'active':''} onClick={()=>setFilter(c)}>{c}</button>)}</div><label className="select-filter"><SlidersHorizontal size={16}/><select value={level} onChange={e=>setLevel(e.target.value)} aria-label="Cấp độ"><option>Tất cả cấp độ</option><option>Nhập môn</option><option>Cơ bản</option><option>Trung cấp</option></select></label></div><div className="catalog-search"><Search size={20}/><input placeholder="Tìm theo tên hoặc nội dung khóa học…" value={search} onChange={e=>setSearch(e.target.value)} aria-label="Tìm trong thư viện"/>{search&&<button className="icon-btn" onClick={()=>setSearch('')} aria-label="Xóa tìm kiếm"><X size={18}/></button>}</div><p className="result-count">{catalog?.total??0} khóa học dành cho bạn{catalogBusy?' · Đang tìm…':''}</p>{filtered.length?<div className={`course-grid catalog-grid ${catalogBusy?'catalog-loading':''}`}>{filtered.map((c:any)=><CourseCard key={c.id} c={c}/>)}</div>:<Blank icon={<Search/>} title="Chưa tìm thấy khóa học" body="Thử một từ khóa khác hoặc chọn Tất cả danh mục." action={<button className="btn secondary" onClick={()=>{setSearch('');setFilter('Tất cả');setLevel('Tất cả cấp độ');}}>Xóa bộ lọc</button>}/>}<Pagination page={catalogPage} total={catalog?.total||0} limit={12} onChange={setCatalogPage}/></>}
 {page==='my'&&<><div className="page-title-row"><div><div className="eyebrow">MỖI BÀI HỌC LÀ MỘT BƯỚC TIẾN</div><h1>Khóa học của tôi</h1><p>{enrolled.length} khóa đã ghi danh · {enrolled.filter(c=>pct(c)===100).length} khóa hoàn thành</p></div><button className="btn secondary" onClick={()=>nav('explore')}><Plus size={17}/> Khám phá khóa mới</button></div>{enrolled.length?<div className="course-grid catalog-grid">{enrolled.map(c=><CourseCard key={c.id} c={c} mine/>)}</div>:<Blank title="Hành trình của bạn đang chờ" body="Ghi danh một khóa học để bắt đầu. Tiến độ sẽ được lưu khi bạn hoàn thành từng bài." action={u?<button className="btn primary" onClick={()=>nav('explore')}>Tìm khóa học đầu tiên <ArrowRight size={17}/></button>:signIn}/>}</>}
 {page==='notes'&&<><div className="page-title-row"><div><div className="eyebrow">GIỮ LẠI NHỮNG ĐIỀU HỮU ÍCH</div><h1>Ghi chú học tập</h1><p>Những ý tưởng và điều bạn muốn nhớ, ở cùng một nơi.</p></div></div>{state.notes.length?<div className="notes-grid">{state.notes.map(n=><button key={n.lesson_id} className="note-card" onClick={()=>nav(`learn/${n.course_id}/${n.lesson_id}`)}><div><NotebookPen size={20}/><small>{date(n.updated_at)}</small></div><span className="overline">{n.course_title}</span><h3>{n.title}</h3><p>{n.body}</p><span className="text-btn">Mở bài học <ArrowUpRight size={16}/></span></button>)}</div>:<Blank icon={<NotebookPen/>} title="Một nơi cho những ý tưởng của bạn" body="Mở một bài học và ghi lại điều bạn muốn nhớ. Ghi chú được lưu riêng cho tài khoản của bạn." action={<button className="btn primary" onClick={()=>nav('my')}>Đến khóa học của tôi</button>}/>}</>}
 {page==='results'&&<><div className="page-title-row"><div><div className="eyebrow">HIỂU MÌNH ĐÃ ĐI ĐƯỢC BAO XA</div><h1>Kết quả luyện tập</h1><p>Xem lại từng lượt quiz và những điều cần ôn thêm.</p></div></div>{state.history.length?<><Suspense fallback={chartLoading}><QuizScoresChart history={state.history} courses={state.courses}/></Suspense><div className="panel table-scroll"><table><thead><tr><th>Khóa học</th><th>Ngày làm</th><th>Kết quả</th><th/></tr></thead><tbody>{state.history.map(a=><tr key={a.id}><td><b>{a.title}</b></td><td>{date(a.submitted_at)}</td><td><span className={`score-pill ${a.score>=70?'good':''}`}>{a.score}/100</span></td><td><button className="text-btn" onClick={()=>mutate(async()=>{const a1=await api((a.kind==='named'?'named-attempt/':'attempts/')+a.id);setAttempt(a1);setModal({type:'result'});})}>Xem đáp án <ArrowUpRight size={15}/></button></td></tr>)}</tbody></table></div></>:<Blank icon={<BarChart3/>} title="Luyện tập để hiểu sâu hơn" body="Hoàn thành quiz trong một khóa học. Điểm và lời giải sẽ xuất hiện tại đây." action={<button className="btn primary" onClick={()=>nav('my')}>Đến khóa học của tôi</button>}/>}</>}
