 {page==='course'&&<><button className="back-link" onClick={()=>nav(u?.role==='ADMIN'&&(current.status==='PENDING_REVIEW'||current.sale_pending_review)?'admin':current.can_manage&&!current.enrolled?'teach':'explore')}><ArrowLeft size={16}/> {u?.role==='ADMIN'&&(current.status==='PENDING_REVIEW'||current.sale_pending_review)?'Về hàng chờ duyệt':current.can_manage&&!current.enrolled?'Về khóa học do tôi tạo':'Quay lại thư viện'}</button><div className="course-detail-hero"><div><div className="card-meta"><span className={`tag ${current.color}`}>{current.category}</span><span>{current.level}</span>{(current.status!=='PUBLISHED'||current.hidden||current.sale_pending_review)&&<span className="tag neutral">{courseStatus(current)}</span>}</div><h1>{current.title}</h1><p>{current.description}</p><div className="detail-facts"><span><BookOpen size={17}/>{current.lessons.length} bài học</span><span><Clock size={17}/>{current.lessons.reduce((n:number,l:any)=>n+l.minutes,0)} phút</span><span><CheckCircle2 size={17}/>Quiz luyện tập</span><span><Wallet size={17}/>{current.price_vnd>0?formatVnd(current.price_vnd)+' mô phỏng':'Miễn phí'}</span></div><div className="button-row">{current.enrolled?<button className="btn primary" disabled={!current.lessons.length||!!current.hidden} onClick={()=>openLesson(current)}>Tiếp tục học <Play size={16}/></button>:<CourseEnrollment key={current.id} course={current} user={u} onEnrolled={async paid=>{await refresh();const c=await loadCurrent();setToast(paid?'Đã mua và ghi danh khóa học.':'Đã ghi danh. Chúc bạn học vui!');if(c.lessons.length)openLesson(c);}}/>}{current.can_edit&&<button className="btn secondary" onClick={()=>nav('edit/'+current.id)}><PenLine size={16}/> Biên soạn</button>}{current.can_manage&&!current.enrolled&&current.lessons.length>0&&<button className="btn secondary" onClick={()=>openLesson(current)}><BookOpen size={16}/> Xem bài học</button>}{current.can_manage&&!current.can_edit&&current.status==='PUBLISHED'&&<button className="btn secondary" onClick={()=>setModal({type:'archive'})}><Archive size={16}/> Lưu trữ</button>}</div>{(current.enrolled||current.owner_id===u?.id)&&['PUBLISHED','ARCHIVED'].includes(current.status)&&!current.hidden&&<p className="course-community-link"><button className="text-btn" onClick={()=>nav('community/'+current.id)}><MessageCircle size={16}/> Thảo luận cùng nhóm học <ArrowUpRight size={14}/></button></p>}{current.hidden===1&&<p className="muted">Khóa học đang tạm ẩn bởi quản trị viên.</p>}</div><Art color={current.color} large/></div><CourseReviewPanel key={current.id} course={current} user={u} onChanged={async message=>{await loadCurrent();await refresh();setToast(message);}}/><div className="detail-grid"><section className="panel"><div className="panel-heading"><h2>Nội dung khóa học</h2><span>{current.lessons.length} bài học</span></div>{current.lessons.map((l:any,i:number)=><button className="lesson-row" key={l.id} onClick={()=>current.enrolled||current.can_manage?nav(`learn/${current.id}/${l.id}`):setToast('Ghi danh khóa học để mở bài này.')}><span className={`lesson-number ${l.completed?'done':''}`}>{l.completed?<Check size={18}/>:String(i+1).padStart(2,'0')}</span><div><b>{l.title}</b><small>{l.type==='VIDEO_LINK'?'Video':'Bài đọc'} · {l.minutes} phút · {l.required?'Bắt buộc':'Tự chọn'}</small></div><ChevronRight size={18}/></button>)}<div className="quiz-row"><span className="lesson-number"><Target size={20}/></span><div><b>Ôn lại điều bạn đã học</b><small>{current.quiz_count} câu hỏi · Có lời giải sau khi nộp</small></div></div></section><aside className="course-detail-aside">{current.enrolled&&<Suspense fallback={chartLoading}><CourseProgressCard lessons={current.lessons}/></Suspense>}<section className="panel detail-tip"><Lightbulb size={27}/><h3>Học một chút, nhớ một chút</h3><p>Đọc bài, ghi lại ý chính bằng lời của bạn, rồi thử quiz để biết mình đã hiểu đến đâu.</p><hr/><p><Check size={16}/> Học theo thời gian của bạn</p><p><Check size={16}/> Lưu tiến độ và ghi chú riêng</p><p><Check size={16}/> Làm lại quiz để luyện tập</p></section></aside></div>{u&&<CourseQuizzes course={current} onChanged={refresh}/>}</>}
 {page==='learn'&&(()=>{const l=current.lessons.find((x:any)=>x.id===lessonId)||current.lessons[0];if(!l)return <Blank title="Chưa có bài học" body="Người tạo khóa học đang chuẩn bị nội dung."/>;if(typeof l.content!=='string')return <Blank title="Ghi danh để bắt đầu" body="Bạn cần ghi danh trước khi đọc nội dung và lưu tiến độ." action={<button className="btn primary" onClick={()=>nav('course/'+id)}>Xem khóa học</button>}/>;return <><button className="back-link" onClick={()=>nav('course/'+id)}><ArrowLeft size={16}/>{current.title}</button><div className="learning-layout"><article className="lesson-paper"><div className="eyebrow">BÀI {l.position} / {current.lessons.length} <span>•</span> {l.minutes} PHÚT ĐỌC</div><h1>{l.title}</h1><div className="lesson-divider"/>{l.type==='VIDEO_LINK'&&l.video_url&&<VideoLesson key={l.id} url={l.video_url}/>}<p className="mandatory-note">{l.required?'Bài bắt buộc — được tính vào tiến độ khóa học.':'Bài tự chọn — bổ sung kiến thức, không tính vào điều kiện hoàn thành.'}</p>{l.content.split('\n\n').map((p:string,i:number)=>{const lines=p.split('\n');return <section className="reading-section" key={i}>{lines.length>1?<><h2>{lines[0]}</h2>{lines.slice(1).map((line:string,n:number)=><p key={n}>{line}</p>)}</>:<p>{p}</p>}</section>})}{l.materials.length>0&&<div className="materials"><h3>Tài liệu đi kèm</h3>{l.materials.map((f:any)=><a key={f.id} href={'/api/files/'+f.id} target="_blank" rel="noreferrer"><FileText size={18}/><span>{f.name}<small>{Math.round(f.size/1024)} KB</small></span><Download size={18}/></a>)}</div>}<div className="lesson-complete"><div><CheckCircle2 size={23}/><div><b>{l.completed?'Bạn đã hoàn thành bài này':'Sẵn sàng cho bước tiếp theo?'}</b><p>Đánh dấu khi bạn đã đọc và hiểu nội dung.</p></div></div><button className="btn primary" disabled={busy||!current.enrolled} onClick={()=>mutate(async()=>{await api('complete',{lesson_id:l.id});await refresh();const c=await loadCurrent();setToast('Đã lưu tiến độ học tập.');const next=c.lessons.find((x:any)=>x.position>l.position&&!x.completed);if(next)nav(`learn/${id}/${next.id}`);})}>{l.completed?'Đã hoàn thành':'Hoàn thành bài'} <Check size={16}/></button></div><section className="notes-editor"><h3><NotebookPen size={19}/> Ghi chú của bạn</h3><textarea aria-label="Nội dung ghi chú" placeholder="Điều quan trọng nhất bạn vừa học được là gì?" value={note} onChange={e=>setNote(e.target.value)} maxLength={5000}/><div><span>Chỉ bạn có thể xem ghi chú này.</span><button className="btn secondary" disabled={busy} onClick={()=>mutate(async()=>{await api('notes',{lesson_id:l.id,body:note});await refresh();await loadCurrent();setToast('Đã lưu ghi chú.');})}><Save size={15}/> Lưu ghi chú</button></div></section></article><aside className="lesson-sidebar panel"><div className="panel-heading"><h3>Hành trình khóa học</h3></div><div className="lesson-progress"><Progress value={Math.round(current.lessons.filter((x:any)=>x.required&&x.completed).length/Math.max(1,current.lessons.filter((x:any)=>x.required).length)*100)}/><small>{current.lessons.filter((x:any)=>x.required&&x.completed).length}/{current.lessons.filter((x:any)=>x.required).length} bài bắt buộc hoàn thành</small></div>{current.lessons.map((x:any)=><button key={x.id} className={`toc-row ${x.id===l.id?'active':''}`} onClick={()=>nav(`learn/${id}/${x.id}`)}><span>{x.completed?<CheckCircle2 size={18}/>:<span className="toc-dot">{x.position}</span>}</span><b>{x.title}</b></button>)}<div className="quiz-invite"><Target size={26}/><h3>Thử sức một chút?</h3><p>{current.quiz_count} câu hỏi để củng cố kiến thức.</p><button className="btn primary" disabled={busy||!current.enrolled||!current.quiz_count} onClick={()=>mutate(async()=>{const a=await api('quiz-start',{course_id:id});setAttempt(a);setAnswers(a.answers);setModal({type:'quiz'});})}>Làm quiz <ArrowRight size={16}/></button></div></aside></div><CourseQuizzes course={current} onChanged={refresh}/><MaterialSearch course={current}/><LabWorkspace course={current}/></>;})()}
